:root{color-scheme:light;--paper:#f8f5ed;--ink:#24281f;--muted:#535a4c;--accent:#374735;--line:#d6d2c5}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{margin:0;background:var(--paper);color:var(--ink);font:1rem/1.6 system-ui,sans-serif}
header,main,footer{width:min(1160px,calc(100% - 48px));margin:auto}
header{min-height:84px;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;border-bottom:1px solid var(--line)}
.brand{font:400 clamp(1.85rem,4vw,2.55rem)/1 Didot,Baskerville,"Times New Roman",serif;letter-spacing:.16em;color:#3b291e;text-decoration:none;padding-inline-start:.16em}
small,footer,.intro,article p,.hint{color:var(--muted)}
.hero{min-height:clamp(520px,68vw,655px);display:grid;grid-template-columns:1fr .95fr;align-items:center;gap:clamp(20px,4vw,54px);margin:18px 0 34px;padding:clamp(26px,5vw,70px);isolation:isolate;overflow:hidden;border-radius:5px;background:radial-gradient(ellipse at 76% 18%,#626a51 0,transparent 56%),linear-gradient(125deg,#222a22,#363e30 66%,#262e27);color:#fff8e9}
.home-intro h1{font:400 clamp(3.3rem,6.3vw,6.25rem)/.99 Didot,Baskerville,Georgia,serif;letter-spacing:-.052em;margin:0}
.home-intro h1 em{font-weight:400;color:#e8dac2}
.home-intro .intro{margin:25px 0 0;color:#f4ebd9;max-width:34ch;font-size:clamp(.98rem,1.7vw,1.1rem)}
.home-intro .actions{align-items:center;gap:12px 20px;margin-top:28px}
.home-intro button{background:#f3e7d2;color:#262e25;border-color:#f3e7d2;border-radius:5px;padding:12px 17px}
.home-intro button span{margin-inline-start:5px}
.home-intro a,.home-intro a:visited{color:#fff8e9;font-size:.9rem;text-underline-offset:4px}
.home-book{margin:0;display:grid;justify-items:center;gap:28px;align-self:center;min-width:0}
.home-book-object{position:relative;width:min(75%,280px);transform:perspective(1150px) rotateY(-15deg) rotateZ(7deg);border-radius:2px 4px 4px 2px;box-shadow:3px 4px 0 #b6a28c,5px 5px 0 #f1e8d7,7px 7px 0 #d5c8b4,9px 9px 0 #e7dccb,11px 11px 0 #a69780,24px 30px 44px #101410ae}
.home-book-object .pregnancy-art{width:100%;border-radius:inherit}
.home-book-object::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:linear-gradient(90deg,#322b2142,transparent 5%,transparent 89%,#fff8eb34)}
.home-book figcaption{color:#eee3ce;text-align:center;font:1rem/1.4 Baskerville,Georgia,serif}
h1,h2,h3{font-family:Georgia,serif;font-weight:400;line-height:1.07;margin:0 0 .38em}
h1{font-size:clamp(3.65rem,8vw,7rem);letter-spacing:-.065em}
h2{font-size:clamp(2rem,5vw,3rem);letter-spacing:-.04em}
h3{font-size:1.6rem}
.intro{max-width:37ch;font-size:1.15rem}
.eyebrow{text-transform:uppercase;letter-spacing:.18em;font-size:.72rem;font-weight:650;color:var(--muted);margin:0 0 24px}
.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
button{border:1px solid var(--accent);border-radius:12px;padding:12px 18px;background:var(--accent);color:white;font:inherit;cursor:pointer}
button.secondary{background:transparent;color:var(--accent)}
button:hover{filter:brightness(1.2)}
:focus-visible{outline:3px solid #945c3d;outline-offset:4px}
.book{width:min(56%,235px);aspect-ratio:.75;display:flex;flex-direction:column;align-items:center;justify-content:space-around;text-align:center;background:repeating-linear-gradient(90deg,#3a493b,#3a493b 2px,#3c4b3d 3px,#3c4b3d 5px);border-left:8px solid #283428;border-radius:3px;color:#f2e6cb;transform:rotate(-9deg);box-shadow:10px 7px 0 #e7dfcd,19px 24px 32px #57483266;padding:14px}
.book strong{font:clamp(1.35rem,4vw,2.6rem)/1.03 Georgia,serif}
.book span{font-size:.64rem;text-transform:uppercase;letter-spacing:.14em}.book i{width:35px;border-top:1px solid #c7b786}
.formats{padding:38px 0;border-top:1px solid var(--line)}
.home-story{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);align-items:center;gap:32px clamp(24px,6vw,78px);padding:clamp(32px,6vw,72px) clamp(8px,2vw,24px)}
.home-story h2{font-size:clamp(2.2rem,4.5vw,3.7rem);text-wrap:balance}
.home-story p{max-width:39ch;color:var(--muted);margin:0}
.home-story .home-book-spread{display:block;min-width:0;margin:0 0 14px}
article,.offer{border:1px solid var(--line);padding:20px;background:#fffdf7}
article p{margin:8px 0 0}
footer{border-top:1px solid var(--line);padding:22px 0;font-size:.88rem}
.work{max-width:680px;margin:48px auto;min-height:410px}
textarea{display:block;width:100%;min-height:125px;resize:vertical;border:1px solid #8b8e80;background:#fffdf7;color:inherit;border-radius:3px;padding:12px;font:inherit;margin-top:8px}
#draft{min-height:320px}
fieldset{border:1px solid var(--line);margin:18px 0;padding:16px}
fieldset label,.offer label{display:block;padding:6px 0}
#status{color:#873b2b}
.receipt{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}
@media(max-width:740px){.hero{grid-template-columns:1fr;gap:34px;padding:32px 24px;margin-top:12px}.home-book-object{width:min(58%,225px)}.home-book{gap:20px}.home-story{grid-template-columns:1fr}}
@media print{header,footer,.formats,.actions,.eyebrow,#status,.print-hide{display:none!important}body{background:white;color:black}main{width:100%}.work{max-width:none;margin:0}.receipt{white-space:pre-wrap}}

/* Store navigation */
header{column-gap:20px}
.header-brand{display:flex;flex-direction:column;align-items:center;text-align:center;justify-self:center}
.account-nav{display:flex;gap:17px;align-items:center;justify-self:end}
.nav-button{display:inline-flex;align-items:center;gap:8px;background:transparent;color:var(--ink);border:0;padding:8px 0;font-size:.88rem;white-space:nowrap}
.profile{width:36px;height:36px;justify-content:center;border:1px solid var(--line);border-radius:50%;flex:none}
.person{display:inline-block;position:relative;width:15px;height:13px;border:1.5px solid currentColor;border-radius:2px}
.person{height:8px;margin-top:8px;border-radius:8px 8px 4px 4px}
.person::before{content:"";position:absolute;width:5px;height:5px;border:1.5px solid currentColor;border-radius:50%;left:3px;top:-10px}
#cart-count{font-size:.74rem;background:#e6ebde;padding:0 6px;border-radius:12px}
.occasion-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.occasion-button{background:#fffdf7;color:var(--accent);border-color:var(--line);border-radius:30px;padding:9px 16px}
.occasion-button:hover{background:#ebece1}

/* Conversation */
.conversation{padding:clamp(15px,4vw,28px);border:1px solid var(--line);background:#fffdf7;border-radius:20px}
.assistant-id{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.assistant-id strong,.assistant-id small{display:block}
.assistant-mark{display:grid;place-items:center;width:42px;height:42px;background:#e8ebdf;color:var(--accent);border-radius:50%;font-size:1.4rem}
.assistant-message{background:#eeefe7;border-radius:4px 15px 15px;padding:16px 18px;margin:0 0 14px}
.assistant-message p{margin:0 0 8px}
.assistant-message h2{font-size:clamp(1.45rem,4vw,2rem);letter-spacing:-.025em;margin:0;overflow-wrap:anywhere}
.customer-message{margin:0 0 14px auto;max-width:85%;background:#f3e7d8;padding:10px 15px;border-radius:15px 4px 15px 15px;overflow-wrap:anywhere;white-space:pre-wrap}
.offer{border-radius:15px}
.saved-items{display:grid;gap:12px}
.saved-items>button{text-align:left;white-space:normal;overflow-wrap:anywhere}
.cart-row{display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:1px solid var(--line);padding-bottom:10px}
@media(max-width:850px){.account-nav{gap:14px}}
@media(max-width:690px){
  header{column-gap:7px;min-height:70px}
  .account-nav{gap:9px}
}
@media(max-width:375px){header,main,footer{width:calc(100% - 28px)}.brand{font-size:1.6rem}.account-nav{gap:8px}}

#photo-files{display:block;max-width:100%;margin:8px 0 18px;font:inherit}
.photo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;margin:16px 0}
.photo-grid:empty{display:none}
.photo-grid figure{margin:0;break-inside:avoid}
.photo-grid img{width:100%;max-height:260px;object-fit:contain;background:#eeeae0;border-radius:5px}
.photo-grid button{padding:5px 9px}

/* Book preview */
.print-book{display:none}
.book-viewer{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;margin:24px 0 28px}
.book-stage{grid-area:1/2;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));min-height:360px;align-content:stretch;border-radius:6px;background:#dfd6c5;padding:0;box-shadow:0 13px 28px #302a201b}
.book-stage.is-cover{place-items:center;grid-template-columns:1fr;padding:22px;background:radial-gradient(ellipse at top,#eae2d2,#d6cab4);box-shadow:none}
.preview-cover{width:min(247px,82%);aspect-ratio:4/5;display:flex;flex-direction:column;justify-content:space-between;align-items:center;text-align:center;padding:24px 18px;color:#f1e4c5;border:1px solid #536353;border-left:9px solid #29382b;border-radius:4px 9px 9px 4px;background:repeating-linear-gradient(90deg,#384939,#384939 2px,#3a4b3b 3px,#3a4b3b 5px);box-shadow:4px 4px 0 #f4edde,7px 6px 0 #af9e81,12px 15px 24px #28201940}
.preview-cover strong{font:clamp(1.45rem,5vw,2.45rem)/1.12 Georgia,serif;overflow-wrap:anywhere}
.preview-cover span:first-child{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase}
.cover-ornament{font-size:1.1rem;color:#d6c69e}
.book-page{position:relative;min-width:0;padding:26px clamp(15px,4vw,33px) 39px;font:1rem/1.5 Georgia,serif;overflow-wrap:anywhere}
.book-page:first-child{border-radius:6px 0 0 6px;background:linear-gradient(90deg,#fffdf6 88%,#e8e0cf)}
.book-page:last-child{border-radius:0 6px 6px 0;background:linear-gradient(90deg,#eae2d1,#fffdf6 12%)}
.book-page p{margin:0 0 .7em}
.book-page p:last-of-type{margin-bottom:0}
.book-page-number{position:absolute;bottom:12px;font:.75rem system-ui,sans-serif;color:var(--muted)}
.book-image-page{display:grid;place-items:center}
.book-image-page img{width:100%;max-height:300px;object-fit:contain;display:block}
.book-page-left .book-page-number{left:28px}
.book-page-right .book-page-number{right:28px}
.book-arrow{width:42px;height:56px;padding:0;font:2.35rem/1 Georgia,serif}
#book-previous{grid-area:1/1}
#book-next{grid-area:1/3}
.book-arrow[aria-disabled="true"]{opacity:.36;cursor:default}
#book-position{grid-area:2/2;font-size:.84rem;text-align:center;color:var(--muted)}
@media(max-width:540px){
  .book-viewer{gap:6px}
  .book-stage{min-height:245px}
  .book-stage.is-cover{min-height:325px}
  .book-page{padding:15px 11px 30px;font-size:.77rem;line-height:1.45}
  .book-page-left .book-page-number{left:11px}
  .book-page-right .book-page-number{right:11px}
  .book-arrow{width:30px;height:46px;font-size:1.75rem}
  #book-position{font-size:.73rem}
}
@media print{.print-book{display:block}}

/* Pregnancy keepsake */
.work.wide-book{max-width:910px}
/* The open spread preserves the PDF proportions at every viewport width. */
.pregnancy-viewer{
  --book-paper:#fdf8f5;
  --book-edge:#eadfd6;
  --book-binding:#d6c8bd;
}
.pregnancy-viewer .book-stage{
  position:relative;
  min-height:0;
  border:0;
  background:var(--book-paper);
}
.pregnancy-viewer .book-stage:not(.is-cover){
  aspect-ratio:595.5/419.25;
  grid-template-rows:minmax(0,1fr);
  border-radius:2px 3px 3px 2px;
  box-shadow:0 0 0 1px #d6c8bd,0 2px 0 var(--book-paper),0 3px 0 var(--book-edge),
    0 4px 0 var(--book-paper),0 6px 0 var(--book-binding),0 14px 24px #4f382c29;
}
.pregnancy-viewer .book-stage:not(.is-cover)::after{
  content:"";
  position:absolute;
  z-index:1;
  pointer-events:none;
  inset:0 auto 0 50%;
  width:clamp(8px,3.5%,32px);
  transform:translateX(-50%);
  background:linear-gradient(90deg,transparent,#5741370e 35%,#57413730 49%,#fffaf3aa 51%,#57413712 64%,transparent);
}
.pregnancy-viewer .book-stage.is-cover{
  background:radial-gradient(ellipse at 35% 20%,#fdf8f5,#eee5dd);
  box-shadow:none;
}
.pregnancy-art{aspect-ratio:297.75/419.25;background-color:#fdf8f5;background-position:center;background-repeat:no-repeat;background-size:contain}
.pregnancy-viewer .preview-cover.pregnancy-art{
  width:min(286px,82%);
  aspect-ratio:297.75/419.25;
  padding:0;
  border:0;
  border-radius:2px 4px 4px 2px;
  box-shadow:3px 3px 0 var(--book-paper),5px 5px 0 var(--book-binding),10px 14px 22px #4f382c30;
}
.preview-formats{display:flex;flex-wrap:wrap;gap:6px 16px;width:fit-content;margin:0 auto 18px;padding:8px 12px;border:1px solid var(--line);border-radius:10px}
.preview-formats legend{padding:0 5px;font-size:.83rem;color:var(--muted)}
.preview-formats label{display:flex;align-items:center;gap:5px;margin:0;cursor:pointer}
.preview-formats input{margin:0;accent-color:#40513c}
.pregnancy-viewer:is([data-binding="hard"],[data-binding="soft"]){
  --book-binding:#fcf7f4;
  --book-binding-edge:#d2c7be;
}
.pregnancy-viewer[data-binding="hard"] .book-stage:not(.is-cover){
  box-shadow:0 7px 0 3px var(--book-binding),0 9px 0 3.5px var(--book-binding-edge),
    0 19px 26px -7px #4937274a;
}
.pregnancy-viewer:is([data-binding="hard"],[data-binding="soft"]) .book-stage:not(.is-cover)::before{
  content:"";position:absolute;inset:100% 0 auto;height:9px;pointer-events:none;
  background:
    linear-gradient(90deg,#76655616,transparent 9%,transparent 47%,#72615441 50%,transparent 54%,transparent 92%,#76655621),
    repeating-linear-gradient(to bottom,#ece3da 0,#fbf7f1 1px,#fefbf6 2px,#d9cec3 3px);
  border-radius:0 0 5px 5px;
}
.pregnancy-viewer[data-binding="hard"] .book-stage:not(.is-cover)::after{
  background:linear-gradient(90deg,transparent,#54443a1a 32%,#45383259 49%,#fffaf3aa 51%,#57413726 67%,transparent);
}
.pregnancy-viewer[data-binding="hard"] .preview-cover.pregnancy-art{
  border:1px solid var(--book-binding-edge);
  box-shadow:2px 2px 0 var(--book-binding-edge),4px 4px 0 #faf6f0,6px 6px 0 #ded3c9,8px 8px 0 #faf6f0,
    10px 10px 0 var(--book-binding),11px 11px 0 var(--book-binding-edge),14px 22px 26px #49372740;
}
.pregnancy-viewer[data-binding="soft"] .book-stage:not(.is-cover){
  border-radius:2px 6px 7px 3px;
  box-shadow:0 0 0 1px var(--book-binding-edge),0 6px 0 var(--book-binding),0 7px 0 var(--book-binding-edge),0 12px 19px -4px #49372744;
}
.pregnancy-viewer[data-binding="soft"] .book-stage:not(.is-cover)::before{
  height:5px;border-radius:0 0 16px 6px;
}
.pregnancy-viewer[data-binding="soft"] .book-stage:not(.is-cover)::after{opacity:.6}
.pregnancy-viewer[data-binding="soft"] .preview-cover.pregnancy-art{
  border-radius:2px 5px 10px 2px;
  transform:perspective(1000px) rotateY(-7deg) rotateZ(-1deg);
  box-shadow:1px 2px 0 #faf6f0,2px 4px 0 var(--book-binding),3px 5px 0 var(--book-binding-edge),5px 9px 14px #49372736;
}
.pregnancy-viewer[data-binding="hard"] .preview-cover.pregnancy-art{
  transform:perspective(1000px) rotateY(-11deg) rotateZ(-2deg);
}
.pregnancy-viewer:is([data-binding="hard"],[data-binding="soft"]) .preview-cover.pregnancy-art::after{
  content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;
  background:linear-gradient(90deg,#5944382b 0%,#59443810 2%,#fff8ec59 3.2%,transparent 6%);
}
.pregnancy-viewer[data-binding="soft"] .preview-cover.pregnancy-art::after{
  background:linear-gradient(105deg,#59443817,transparent 8%,transparent 83%,#fffaf383 96%,#88796925);
}
.pregnancy-viewer[data-binding="pdf"] .book-stage:not(.is-cover){
  gap:6px;background:transparent;border-radius:0;box-shadow:none;
}
.pregnancy-viewer[data-binding="pdf"] .book-stage::after{content:none}
.pregnancy-viewer[data-binding="pdf"] .book-stage.is-cover{background:transparent}
.pregnancy-viewer[data-binding="pdf"] :is(.preview-cover.pregnancy-art,.book-stage .book-page){
  border-radius:0;box-shadow:0 0 0 1px #d8cec3;
}
.pregnancy-viewer[data-binding="pdf"] .book-stage .book-endpaper{visibility:hidden}
.pregnancy-picker{display:grid;grid-template-columns:minmax(0,190px) 1fr;gap:26px;align-items:center}
.pregnancy-picker .pregnancy-art{border:1px solid var(--line);box-shadow:4px 5px 10px #302a201b}
.pregnancy-choices{display:grid;gap:10px;margin:18px 0}
.pregnancy-choices button{border-radius:16px}
@media(max-width:540px){.pregnancy-picker{grid-template-columns:1fr}.pregnancy-picker .pregnancy-art{width:132px}}
.pregnancy-viewer .book-page{padding:36px clamp(20px,4vw,45px) 48px;font-size:1.04rem}
.pregnancy-viewer .book-page h3{color:#49563b;font-size:clamp(1.35rem,4vw,2rem);margin-bottom:.7em}
.pregnancy-viewer .book-page:first-child,.pregnancy-viewer .book-page:last-child{background:var(--book-paper)}
.pregnancy-viewer .book-page:first-child{border-radius:2px 0 0 2px}
.pregnancy-viewer .book-page:last-child{border-radius:0 3px 3px 0}
.pregnancy-viewer .book-page{min-height:0}
.pregnancy-viewer .book-page:not(.original-book-page){overflow:auto}
.pregnancy-viewer .book-title{display:grid;place-content:center;text-align:center}
.pregnancy-viewer .book-title::before{content:"✦";color:#85734a;margin-bottom:16px}
.pregnancy-viewer .book-image-page img{max-height:375px;max-width:100%;width:auto;border:8px solid #fffaf0;box-shadow:1px 3px 12px #4f3c2b35;transform:rotate(-1deg)}
.book-writing-lines{height:138px;background:repeating-linear-gradient(transparent 0 27px,#ded4bd 28px 29px)}
.book-photo-placeholder{display:grid;place-items:center;min-height:180px;border:1px dashed #b8a88a;color:#635b49;text-align:center}
@media(max-width:540px){
  .pregnancy-viewer .book-stage.is-cover{min-height:310px}
  .pregnancy-viewer .book-page{padding:18px 11px 33px;font-size:.77rem}
  .pregnancy-viewer .book-page h3{font-size:clamp(.95rem,3.5vw,1.2rem)}
  .pregnancy-viewer .book-image-page img{border-width:4px}
  .book-photo-placeholder{min-height:110px}
}

#photo-editor{margin:14px 0;padding:clamp(14px,3vw,24px);border:1px solid var(--line);border-radius:16px;background:#fffdf8}
#photo-editor h3{font-size:1.42rem;margin:0}
#photo-editor input{display:block;max-width:100%;margin:6px 0;font:inherit}
.photo-editor-toolbar{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}
.photo-editor-controls{display:flex;align-items:end;flex-wrap:wrap;gap:12px}
.photo-editor-controls label,.photo-crop-controls label{display:grid;gap:5px;font-size:.82rem;color:var(--muted)}
.photo-editor-controls select,.photo-move select{font:inherit;max-width:100%;border:1px solid var(--line);border-radius:8px;padding:7px 10px;color:var(--ink);background:#fffdf8}
.photo-editor-controls .photo-upload{display:block;position:relative;border:1px solid #5b6a53;border-radius:8px;color:#34452e;padding:7px 12px;cursor:pointer}
#photo-editor .photo-upload input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}
.photo-upload:focus-within{outline:2px solid #856047;outline-offset:2px}
.photo-editor-more{border-top:1px solid var(--line);margin-top:12px;padding-top:10px}
.photo-editor-more>summary{font-size:.88rem;color:#34452e;cursor:pointer;width:fit-content}
.book-order-summary{margin:20px 0 0;padding:clamp(17px,3vw,26px);border:1px solid var(--line);border-radius:16px;background:#fffdf8}
.book-order-summary header{display:flex;justify-content:space-between;align-items:start;flex-wrap:wrap;gap:10px 20px;width:100%;min-height:0;margin:0;border:0}
.book-order-summary h3{margin:0;font-size:1.45rem}
.book-order-summary header p{margin:4px 0 0;color:var(--muted);font-size:.85rem}
.book-order-total{display:grid;text-align:right;gap:2px;color:#34452e}
.book-order-total span{font-size:.83rem}
.book-order-total strong{font-size:1.8rem;line-height:1.12;font-variant-numeric:tabular-nums}
.book-order-summary dl{margin:14px 0 0;border-top:1px solid var(--line)}
.book-order-summary dl>div{display:flex;justify-content:space-between;gap:12px;padding:7px 0;border-bottom:1px solid #e9e2d8}
.book-order-summary dd{margin:0;white-space:nowrap;font-variant-numeric:tabular-nums}
.book-order-summary .actions{margin-top:16px}
.book-order-summary>.hint{margin:10px 0 0;font-size:.83rem}
